package com.aistock.prediction.marketuse;
import com.aistock.prediction.analysis.AnalysisRepository;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.context.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.EnableScheduling;
@Configuration(proxyBeanMethods=false) public class MarketUseConfiguration {
 @Bean MarketUseClient marketUseClient(@Value("${aistock.forecast.market-url:http://127.0.0.1:18082}")String base,@Value("${aistock.internal.token:}")String token){return new MarketUseClient(base,token,Duration.ofSeconds(4));}
 @Bean MarketUseOwnerService marketUseOwner(JdbcTemplate jdbc,ObjectMapper json,AnalysisRepository analyses,MarketUseClient client,Clock clock,@Value("${aistock.market-use.analysis-enabled:false}")boolean enabled){return new MarketUseOwnerService(jdbc,json,analyses,client,clock,enabled);}
 @Bean PredictionMarketUseOwner predictionMarketUseOwner(JdbcTemplate jdbc,ObjectMapper json,com.aistock.prediction.forecast.ForecastRepository forecasts,com.aistock.prediction.verification.VerificationRepository verifications,MarketUseClient client,Clock clock,@Value("${aistock.market-use.forecast-enabled:false}")boolean forecast,@Value("${aistock.market-use.verification-enabled:false}")boolean verification){return new PredictionMarketUseOwner(jdbc,json,forecasts,verifications,client,clock,forecast,verification);}
 @Bean ComparisonMarketUseOwner comparisonMarketUseOwner(JdbcTemplate jdbc,ObjectMapper json,com.aistock.prediction.comparison.ComparisonRepository comparisons,MarketUseClient client,Clock clock,@Value("${aistock.market-use.comparison-enabled:false}")boolean enabled){return new ComparisonMarketUseOwner(jdbc,json,comparisons,client,clock,enabled);}
 @Bean PortfolioMarketUseOwner portfolioMarketUseOwner(JdbcTemplate jdbc,ObjectMapper json,com.aistock.prediction.portfolioanalysis.PortfolioRepository portfolios,MarketUseClient client,Clock clock,@Value("${aistock.market-use.portfolio-enabled:false}")boolean enabled){return new PortfolioMarketUseOwner(jdbc,json,portfolios,client,clock,enabled);}
 @Bean MarketUseRecovery marketUseRecovery(MarketUseOwnerService owner,PredictionMarketUseOwner predictions,ComparisonMarketUseOwner comparisons,PortfolioMarketUseOwner portfolios,@Value("${aistock.market-use.analysis-enabled:false}")boolean analysis,@Value("${aistock.market-use.recovery-enabled:false}")boolean recovery){return new MarketUseRecovery(owner,predictions,comparisons,portfolios,analysis,recovery);}
 @Configuration(proxyBeanMethods=false) @ConditionalOnProperty(name="aistock.market-use.recovery-enabled",havingValue="true") @EnableScheduling static class Scheduling{}
}
